import{_ as t,o as a,c as r,a0 as s}from"./chunks/framework.BxrwG5q5.js";const h=JSON.parse('{"title":"Prerequisites","description":"","frontmatter":{},"headers":[],"relativePath":"features/prerequisites.md","filePath":"features/prerequisites.md"}'),i={name:"features/prerequisites.md"};function n(o,e,l,d,u,g){return a(),r("div",null,[...e[0]||(e[0]=[s(`<h1 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h1><blockquote><p>See also: <a href="/config/features/targeting.html">Targeting Rules</a> · <a href="/config/features/scheduling.html">Scheduling</a> · <a href="/config/features/rollouts.html">Percentage Rollouts</a></p></blockquote><p>Prerequisites are <strong>dependency flags</strong> — a flag that guards another flag. &quot;Feature B only activates if Feature A is already in the required state.&quot; This is <strong>dependency-based feature gating</strong>: preventing a dependent feature from being enabled without its guard flag passing first.</p><p>The flag that is depended upon is often called a <strong>guard flag</strong> — it acts as a gate in the evaluation pipeline.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>New checkout</strong> requires <strong>payment v2</strong> guard flag to be <code>true</code></li><li><strong>Dark mode</strong> requires <strong>theme engine</strong> guard flag to be <code>active</code></li><li><strong>Admin panel</strong> requires <code>user.role</code> config to equal <code>&quot;admin&quot;</code></li><li><strong>Canary feature</strong> requires <strong>kill-switch flag</strong> to be <code>true</code> (instant disable by flipping the guard)</li></ul><h2 id="setting-up-prerequisites" tabindex="-1">Setting Up Prerequisites <a class="header-anchor" href="#setting-up-prerequisites" aria-label="Permalink to &quot;Setting Up Prerequisites&quot;">​</a></h2><ol><li>Open a config in the portal</li><li>Expand the <strong>Prerequisites</strong> section</li><li>Select a guard flag from the dropdown</li><li>Choose an operator and required value</li><li>Click <strong>Add</strong></li></ol><h2 id="supported-operators" tabindex="-1">Supported Operators <a class="header-anchor" href="#supported-operators" aria-label="Permalink to &quot;Supported Operators&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operator</th><th>Use Case</th></tr></thead><tbody><tr><td><code>equals</code></td><td>Guard flag must have this exact value</td></tr><tr><td><code>not_equals</code></td><td>Guard flag must NOT have this value</td></tr><tr><td><code>greater_than</code></td><td>Numeric guard flag must be above threshold</td></tr><tr><td><code>less_than</code></td><td>Numeric guard flag must be below threshold</td></tr><tr><td><code>contains</code></td><td>String guard flag must contain substring</td></tr></tbody></table><p>Operators are filtered by the guard flag&#39;s type — boolean flags show only <code>equals</code> / <code>not_equals</code>.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><ol><li>Each prerequisite (guard flag) is evaluated in order</li><li>If ANY guard flag condition is unmet → the config returns its default value immediately</li><li>If ALL guard flags pass → evaluation continues to targeting/rollout</li></ol><h2 id="circular-dependency-protection" tabindex="-1">Circular Dependency Protection <a class="header-anchor" href="#circular-dependency-protection" aria-label="Permalink to &quot;Circular Dependency Protection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Protection</th><th>Behavior</th></tr></thead><tbody><tr><td>Self-reference</td><td>A flag cannot require itself</td></tr><tr><td>Circular chains</td><td>A → B → A is detected and breaks the loop</td></tr><tr><td>Depth limit</td><td>Maximum 5 levels of prerequisite nesting</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>feature.checkout_v2:</span></span>
<span class="line"><span>  prerequisites:</span></span>
<span class="line"><span>    - feature.payments_v2 equals true    ← guard flag</span></span>
<span class="line"><span>    - app.min_version greater_than 2.0   ← guard flag</span></span>
<span class="line"><span>  targeting:</span></span>
<span class="line"><span>    - If user in &quot;Beta Testers&quot; → true</span></span>
<span class="line"><span>  default: false</span></span></code></pre></div><p>Even if a user is in &quot;Beta Testers&quot;, they get <code>false</code> unless both guard flags pass. The prerequisite check is a hard gate above targeting in the pipeline.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/config/features/targeting.html">Targeting Rules</a> — Prerequisites gate the targeting step; see feature gating via targeting</li><li><a href="/config/features/segments.html">Segments</a> — Combine guard flags with segment-based targeting</li><li><a href="/config/features/scheduling.html">Scheduling</a> — Schedule a flag that has guard flags defined</li><li><a href="/config/features/rollouts.html">Percentage Rollouts</a> — Rollouts only evaluate if all guard flags pass</li><li><a href="/config/features/audit-log.html">Audit Log</a> — Track guard flag additions and removals</li></ul>`,20)])])}const p=t(i,[["render",n]]);export{h as __pageData,p as default};
